import java.util.*;
import ru.bccontrol.sedonastudio.model.*;import ru.bccontrol.sedonastudio.storage.*;
public class EditorTests {
 static void check(boolean b,String name){if(!b)throw new AssertionError(name);}
 public static void main(String[] args)throws Exception{
  Project p=new Project();List<Project.Node> types=Catalog.bundled();Project.Node folder=new Project.Node();folder.id="f";folder.name="folder";folder.type="sys::Folder";folder.kitPart="sys-00000001";p.parts.add(folder.kitPart);p.nodes.put("f",folder);
  Project.Node a=types.get(0).copy(),b=types.get(2).copy(),c=types.get(2).copy();a.id="a";a.name="src";a.parent="f";a.note="Source documentation";a.x=60;a.y=60;b.id="b";b.name="sum";b.parent="f";b.x=360;b.y=60;c.id="c";c.name="sink";c.parent="0";c.x=660;c.y=60;
  for(Project.Node n:List.of(a,b,c)){p.nodes.put(n.id,n);if(!p.parts.contains(n.kitPart))p.parts.add(n.kitPart);}p.connect("a","out","b","in1");p.connect("b","out","c","in1");p.wires.get(0).bends.add(new Project.Point(300,120));check(p.validate().isEmpty(),"Fixture");
  Project clip=EditorCommands.fragment(p,List.of("f"));check(clip.nodes.size()==3&&clip.wires.size()==1,"Subtree clipboard internal wires only");
  History h=new History();h.reset(p);p.nodes.get("a").note="External mutation";check(h.get().nodes.get("a").note.equals("Source documentation"),"Detached reset");
  Set<String> added=new LinkedHashSet<>();h.edit(next->added.addAll(EditorCommands.paste(next,clip,"0",36)));check(added.size()==1&&h.get().nodes.size()==7,"Paste subtree new ids");check(h.get().wires.size()==3,"Copied internal edge");check(h.undo()&&h.get().nodes.size()==4,"Paste undo");check(h.redo()&&h.get().nodes.size()==7,"Paste redo");h.undo();
  h.edit(next->EditorCommands.relocate(next,List.of("a","b"),"0"));check(!h.get().nodes.containsKey("a")&&!h.get().nodes.containsKey("b"),"Relocation new IDs");check(h.get().wires.size()==2&&h.get().wires.stream().anyMatch(w->w.target.equals("c")),"External edges retained");check(h.get().validate().isEmpty(),"Relocated graph valid");h.undo();
  String before=ProjectStore.encode(h.get());boolean failed=false;try{h.edit(next->EditorCommands.relocate(next,List.of("f"),"a"));}catch(IllegalArgumentException expected){failed=true;}check(failed&&before.equals(ProjectStore.encode(h.get())),"Cycle rejection atomic");
  Project copy=ProjectStore.decode(ProjectStore.encode(h.get()));check(copy.nodes.get("a").note.equals("Source documentation")&&copy.wires.get(0).bends.size()==1,"Local metadata roundtrip");
  copy.wires.get(0).bends.clear();check(h.get().wires.get(0).bends.size()==1,"Detached bend copy");
  h.edit(next->EditorCommands.move(next,Map.of("a",new double[]{84,84},"b",new double[]{384,84})));check(h.get().wires.get(0).bends.get(0).x()==324,"Group manual route moves");h.undo();
  Project fragment=EditorCommands.fragment(h.get(),List.of("a","b"));Project target=h.get().copy();Set<String> inserted=EditorCommands.paste(target,fragment,"0",48);Project.Wire edge=target.wires.get(target.wires.size()-1);check(edge.bends.get(0).x()==348,"Pasted root manual route offset");
  Project branch=new Project();for(String id:List.of("a","b","c","d")){Project.Node n=a.copy();n.id=id;branch.nodes.put(id,n);}branch.wires.add(new Project.Wire("a","out","b","in1"));branch.wires.add(new Project.Wire("c","out","b","in2"));branch.wires.add(new Project.Wire("c","out","d","in1"));check(EditorCommands.signalPath(branch,"a").equals(Set.of("a","b")),"Directed signal path excludes sibling branches");
  java.nio.file.Path recovery=java.nio.file.Files.createTempDirectory("studio-recovery-").resolve("draft.json");ProjectStore.save(h.get(),recovery);String backup=ProjectStore.encode(h.get());java.nio.file.Files.writeString(recovery.resolveSibling("draft.json.bak"),backup);java.nio.file.Files.writeString(recovery,"{broken");Project recovered=ProjectStore.loadRecovering(recovery);check(ProjectStore.encode(recovered).equals(backup),"Backup recovery");check(java.nio.file.Files.readString(recovery.resolveSibling("draft.json.bak")).equals(backup),"Valid backup preserved");try(var files=java.nio.file.Files.list(recovery.getParent())){check(files.anyMatch(f->f.getFileName().toString().startsWith("draft.json.damaged-")),"Corrupt original retained");}System.out.println("PASS recovery: corrupted draft restored, valid backup and damaged original preserved");
  System.out.println("PASS editor commands: subtree+internal links copy, unique IDs, group paste undo/redo, folder relocation+external links, cycle atomicity, detached reset, comments and manual route persistence");
 }
}
